import { APP_ROUTES } from '@/constants/app-routes';
import { ORIGEM_FASE_MAP } from '@/constants/due-diligence';
import { AppRouterInstance } from 'next/dist/shared/lib/app-router-context.shared-runtime';
import { ActiveViewType } from '../enums';
import { TDueDiligenceDetailedCardItem } from '../types/dueItem';
import { normalizeStatusIdwall, type TStatusIdwall } from './idwall-status';
import { formatCurrency } from '@/functions/formaters/formatCurrency';
import { toNumberOrZero } from '@/functions/memoria';

type DueObsCessaoIdwallFields = Pick<
    TDueDiligenceDetailedCardItem,
    'observacoes_count' | 'cessionarios_vinculados' | 'status_idwall'
>;

export type {
    CreateDueCardScreenHandlersParams,
    TDueCardActionHandlers,
    TDueCardNavigationHandlers,
    TDueCardPatchHandlersInput,
    TDueCardScreenHandlers,
} from '../interfaces/handlers';
export { createDueCardScreenHandlers } from './DueCard/create-screen-handlers';
export { isDueDiligencePipelineItem } from './isDueDiligencePipelineItem';
export { resolveEffectiveStatusLiquidacao } from './resolve-effective-status-liquidacao';
export {
    buildResponsavelDueAtivoViewData,
    getResponsavelFullName,
    getResponsavelInitials,
    getResponsavelName,
    type TResponsavelDueAtivoViewData,
} from './responsavelViewData';
export * from './scrollUtils';

export function navigateToDueDiligenceMain(router: AppRouterInstance): void {
    const urlParams = new URLSearchParams(window.location.search);
    const prevPageParams = urlParams.get('prevPageParams');

    if (prevPageParams) {
        void router.push(`${APP_ROUTES.private.dueDiligence2.name}${prevPageParams}`);
        return;
    }

    void router.push(APP_ROUTES.private.dueDiligence2.name);
}

export function getPhaseFromUrl(): ActiveViewType | null {
    const urlParams = new URLSearchParams(window.location.search);
    const encodedParams = urlParams.get('prevPageParams');

    if (!encodedParams) return null;

    try {
        const decodedString = decodeURIComponent(encodedParams).replace(/^\?/, '');
        const innerParams = new URLSearchParams(decodedString);

        return (innerParams.get('activeView') as ActiveViewType) || ActiveViewType.DUE_DILIGENCE;
    } catch (e) {
        console.error('Erro ao decodificar parâmetros:', e);
        return null;
    }
}

export function getObsCount(item: DueObsCessaoIdwallFields): number {
    return item.observacoes_count ?? 0;
}

export function buildPathWithPrevParams(basePath: string): string {
    if (typeof window === 'undefined') return basePath;

    const urlParams = new URLSearchParams(window.location.search);

    const prevValue = urlParams.get('prevPageParams') ?? window.location.search;
    if (!prevValue) return basePath;

    const queryIndex = basePath.indexOf('?');
    const pathname = queryIndex === -1 ? basePath : basePath.slice(0, queryIndex);
    const nextParams = new URLSearchParams(queryIndex === -1 ? '' : basePath.slice(queryIndex + 1));
    nextParams.set('prevPageParams', prevValue);
    const qs = nextParams.toString();
    return qs ? `${pathname}?${qs}` : pathname;
}

/** Remove lixo de query embutido no filtro (ex.: credor com `?prevPageParams=` por URL malformada). */
export function sanitizePendenciasCredorFilter(raw: string): string {
    const trimmed = raw.trim();
    const cut = trimmed.search(/[?&]/);
    return cut === -1 ? trimmed : trimmed.slice(0, cut).trim();
}

export function getTotalPctCessao(
    item: Pick<TDueDiligenceDetailedCardItem, 'cessionarios_vinculados'>,
): number {
    return (item.cessionarios_vinculados ?? []).reduce(
        (total, vinculo) => total + toNumberOrZero(vinculo.percentual),
        0,
    );
}

export function getIdwallStatus(
    item: Pick<TDueDiligenceDetailedCardItem, 'status_idwall'>,
): TStatusIdwall {
    return normalizeStatusIdwall(item.status_idwall);
}

export { normalizeStatusIdwall } from './idwall-status';
export type { TStatusIdwall } from './idwall-status';

export function getOrigemLabel(fase?: string): string {
    if (!fase) return 'N/A';
    return ORIGEM_FASE_MAP[fase.toLowerCase()] ?? fase;
}

export {
    countOpenPendencias,
    getPendenciasData,
    hasOpenImpeditivaPendencia,
} from './getPendenciasData';

export interface IHeaderInfoItem {
    label: string;

